#include <torch/extension.h>
#include <c10/util/Optional.h>

at::Tensor conv_transpose3d_forward(
    at::Tensor x,
    at::Tensor weight,
    c10::optional<at::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h>

namespace {

constexpr int TILE = 8;
constexpr int IN_TILE = TILE + 2;      // 10 for K=3, stride=1, pad=0
constexpr int IN_TILE_FLOATS = IN_TILE * IN_TILE * IN_TILE;  // 1000
constexpr int K3 = 27;
constexpr int CO_BLOCK = 16;
constexpr int W_TILE_FLOATS = CO_BLOCK * K3;                  // 432
constexpr int SPECIAL_THREADS = TILE * TILE * TILE;           // 512

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int Cin, int Di, int Hi, int Wi,
    int Cout, int Do, int Ho, int Wo,
    int Kd, int Kh, int Kw,
    int stride, int padding, int output_padding, int groups,
    bool has_bias,
    bool special)
{
    if (special) {
        // Fast path for the provided shape family:
        // K=3, stride=1, padding=0, output_padding=0, groups=1, dilation=1, float32.
        extern __shared__ float smem[];
        float* s_in = smem;                       // 10^3 input tile for one input channel
        float* s_w  = smem + IN_TILE_FLOATS;      // 16 output channels x 27 taps for current ci

        const int tid = threadIdx.x;
        const int rx = tid & (TILE - 1);
        const int ry = (tid >> 3) & (TILE - 1);
        const int rz = tid >> 6;

        const int tiles_x = (Wo + TILE - 1) / TILE;
        const int tiles_y = (Ho + TILE - 1) / TILE;
        const int tx = blockIdx.x % tiles_x;
        const int ty = (blockIdx.x / tiles_x) % tiles_y;
        const int tz = blockIdx.x / (tiles_x * tiles_y);

        const int n = blockIdx.z;
        const int co0 = blockIdx.y * CO_BLOCK;

        const int ox = tx * TILE + rx;
        const int oy = ty * TILE + ry;
        const int oz = tz * TILE + rz;
        const bool out_valid = (ox < Wo) && (oy < Ho) && (oz < Do);

        const int in_base_x = tx * TILE - 2;
        const int in_base_y = ty * TILE - 2;
        const int in_base_z = tz * TILE - 2;

        float acc[CO_BLOCK];
#pragma unroll
        for (int c = 0; c < CO_BLOCK; ++c) acc[c] = 0.0f;

        for (int ci = 0; ci < Cin; ++ci) {
            // Load input tile for (n, ci), with zero halo outside input bounds.
            for (int idx = tid; idx < IN_TILE_FLOATS; idx += SPECIAL_THREADS) {
                const int lz = idx / (IN_TILE * IN_TILE);
                const int rem = idx - lz * (IN_TILE * IN_TILE);
                const int ly = rem / IN_TILE;
                const int lx = rem - ly * IN_TILE;

                const int gx = in_base_x + lx;
                const int gy = in_base_y + ly;
                const int gz = in_base_z + lz;

                float v = 0.0f;
                if (gx >= 0 && gx < Wi && gy >= 0 && gy < Hi && gz >= 0 && gz < Di) {
                    const int64_t xoff = (((int64_t)n * Cin + ci) * Di + gz) * Hi * Wi +
                                         ((int64_t)gy * Wi + gx);
                    v = x[xoff];
                }
                s_in[idx] = v;
            }

            // Load weights for this input channel and this block of output channels.
            for (int idx = tid; idx < W_TILE_FLOATS; idx += SPECIAL_THREADS) {
                const int lc = idx / K3;
                const int tap = idx - lc * K3;
                const int co = co0 + lc;
                float v = 0.0f;
                if (co < Cout) {
                    const int64_t woff = ((int64_t)ci * Cout + co) * K3 + tap;
                    v = w[woff];
                }
                s_w[idx] = v;
            }
            __syncthreads();

            if (out_valid) {
#pragma unroll
                for (int tap = 0; tap < K3; ++tap) {
                    const int kd = tap / 9;
                    const int rem = tap - kd * 9;
                    const int kh = rem / 3;
                    const int kw = rem - kh * 3;

                    const int sx = rx + 2 - kw;
                    const int sy = ry + 2 - kh;
                    const int sz = rz + 2 - kd;
                    const float xv = s_in[(sz * IN_TILE + sy) * IN_TILE + sx];

#pragma unroll
                    for (int c = 0; c < CO_BLOCK; ++c) {
                        acc[c] = fmaf(xv, s_w[c * K3 + tap], acc[c]);
                    }
                }
            }
            __syncthreads();
        }

        if (out_valid) {
#pragma unroll
            for (int c = 0; c < CO_BLOCK; ++c) {
                const int co = co0 + c;
                if (co < Cout) {
                    const int64_t yoff = (((int64_t)n * Cout + co) * Do + oz) * Ho * Wo +
                                         ((int64_t)oy * Wo + ox);
                    y[yoff] = acc[c] + (has_bias ? b[co] : 0.0f);
                }
            }
        }
    } else {
        // Correct generic fallback, still using this same single CUDA kernel.
        const int64_t total = (int64_t)N * Cout * Do * Ho * Wo;
        const int64_t step = (int64_t)gridDim.x * blockDim.x;
        const int co_per_group = Cout / groups;
        const int ci_per_group = Cin / groups;

        for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
             idx < total; idx += step) {
            int64_t t = idx;
            const int ox = (int)(t % Wo); t /= Wo;
            const int oy = (int)(t % Ho); t /= Ho;
            const int oz = (int)(t % Do); t /= Do;
            const int co = (int)(t % Cout);
            const int n  = (int)(t / Cout);

            const int g = co / co_per_group;
            const int co_local = co - g * co_per_group;
            const int ci_begin = g * ci_per_group;
            const int ci_end = ci_begin + ci_per_group;

            float sum = has_bias ? b[co] : 0.0f;

            for (int ci = ci_begin; ci < ci_end; ++ci) {
                for (int kd = 0; kd < Kd; ++kd) {
                    const int nz = oz + padding - kd;
                    if (nz < 0 || (nz % stride) != 0) continue;
                    const int iz = nz / stride;
                    if (iz < 0 || iz >= Di) continue;

                    for (int kh = 0; kh < Kh; ++kh) {
                        const int ny = oy + padding - kh;
                        if (ny < 0 || (ny % stride) != 0) continue;
                        const int iy = ny / stride;
                        if (iy < 0 || iy >= Hi) continue;

                        for (int kw = 0; kw < Kw; ++kw) {
                            const int nx = ox + padding - kw;
                            if (nx < 0 || (nx % stride) != 0) continue;
                            const int ix = nx / stride;
                            if (ix < 0 || ix >= Wi) continue;

                            const int64_t xoff =
                                (((int64_t)n * Cin + ci) * Di + iz) * Hi * Wi +
                                ((int64_t)iy * Wi + ix);
                            const int64_t woff =
                                ((((int64_t)ci * co_per_group + co_local) * Kd + kd) * Kh + kh) * Kw + kw;
                            sum = fmaf(x[xoff], w[woff], sum);
                        }
                    }
                }
            }
            y[idx] = sum;
        }
    }
}

inline int64_t conv_transpose_out_size(int64_t in, int64_t k, int64_t stride,
                                       int64_t padding, int64_t output_padding) {
    return (in - 1) * stride - 2 * padding + (k - 1) + output_padding + 1;
}

} // namespace

at::Tensor conv_transpose3d_forward(
    at::Tensor x,
    at::Tensor weight,
    c10::optional<at::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D");
    TORCH_CHECK(stride >= 1 && padding >= 0 && output_padding >= 0 && groups >= 1);

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    const int64_t N = xc.size(0);
    const int64_t Cin = xc.size(1);
    const int64_t Di = xc.size(2);
    const int64_t Hi = xc.size(3);
    const int64_t Wi = xc.size(4);

    const int64_t Kd = wc.size(2);
    const int64_t Kh = wc.size(3);
    const int64_t Kw = wc.size(4);

    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    const int64_t Cout = wc.size(1) * groups;
    TORCH_CHECK(wc.size(0) == Cin, "bad conv_transpose3d weight shape");

    const int64_t Do = conv_transpose_out_size(Di, Kd, stride, padding, output_padding);
    const int64_t Ho = conv_transpose_out_size(Hi, Kh, stride, padding, output_padding);
    const int64_t Wo = conv_transpose_out_size(Wi, Kw, stride, padding, output_padding);

    auto y = at::empty({N, Cout, Do, Ho, Wo}, xc.options());

    const bool has_bias = bias.has_value() && bias->defined();
    at::Tensor bc;
    const float* bptr = nullptr;
    if (has_bias) {
        bc = bias->contiguous();
        TORCH_CHECK(bc.is_cuda() && bc.scalar_type() == at::kFloat && bc.numel() == Cout);
        bptr = bc.data_ptr<float>();
    }

    const bool special =
        Kd == 3 && Kh == 3 && Kw == 3 &&
        stride == 1 && padding == 0 && output_padding == 0 && groups == 1 &&
        Di == Hi && Hi == Wi && Do == Di + 2 && Ho == Hi + 2 && Wo == Wi + 2;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (special) {
        const int tiles_x = (int)((Wo + TILE - 1) / TILE);
        const int tiles_y = (int)((Ho + TILE - 1) / TILE);
        const int tiles_z = (int)((Do + TILE - 1) / TILE);
        const int spatial_tiles = tiles_x * tiles_y * tiles_z;
        const int co_blocks = (int)((Cout + CO_BLOCK - 1) / CO_BLOCK);

        dim3 block(SPECIAL_THREADS);
        dim3 grid(spatial_tiles, co_blocks, (unsigned)N);
        const size_t smem_bytes = (IN_TILE_FLOATS + W_TILE_FLOATS) * sizeof(float);

        conv_transpose3d_kernel<<<grid, block, smem_bytes, stream>>>(
            xc.data_ptr<float>(), wc.data_ptr<float>(), bptr, y.data_ptr<float>(),
            (int)N, (int)Cin, (int)Di, (int)Hi, (int)Wi,
            (int)Cout, (int)Do, (int)Ho, (int)Wo,
            (int)Kd, (int)Kh, (int)Kw,
            (int)stride, (int)padding, (int)output_padding, (int)groups,
            has_bias, true);
    } else {
        const int64_t total = (int64_t)N * Cout * Do * Ho * Wo;
        const int block = 256;
        int64_t wanted = (total + block - 1) / block;
        int grid = (int)std::min<int64_t>(wanted, 32768);
        if (grid < 1) grid = 1;

        conv_transpose3d_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(), wc.data_ptr<float>(), bptr, y.data_ptr<float>(),
            (int)N, (int)Cin, (int)Di, (int)Hi, (int)Wi,
            (int)Cout, (int)Do, (int)Ho, (int)Wo,
            (int)Kd, (int)Kh, (int)Kw,
            (int)stride, (int)padding, (int)output_padding, (int)groups,
            has_bias, false);
    }

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
